<?php
namespace Modules\Ran\Http\Controllers;
use Modules\Ran\Entities\{Transfer,StockLot};use Modules\Ran\Http\Requests\TransferRequest;use Modules\Ran\Services\TransferService;
class TransferController extends RanController {public function index(){return view('ran::transfers.index',array_merge($this->pageOptions(),['transfers'=>Transfer::latest('transfer_date')->latest('id')->paginate(25)]));} public function create(){return view('ran::transfers.form',array_merge($this->pageOptions(),['lots'=>StockLot::with('item')->where('stock_status','available')->orderBy('lot_no')->get()]));} public function store(TransferRequest $request,TransferService $service){$transfer=$service->create($request->validated());return $this->success('Transfer created.','ran.transfers.show',[$transfer]);} public function show(Transfer $transfer){return view('ran::transfers.show',array_merge($this->pageOptions(),['transfer'=>$transfer->load('lines.stockLot.item')]));} public function dispatch(Transfer $transfer,TransferService $service){$service->dispatch($transfer);return back()->with('status','Transfer dispatched.');} public function receive(Transfer $transfer,TransferService $service){$service->receive($transfer);return back()->with('status','Transfer received into destination store.');}}
